import React, { useEffect, useRef } from 'react';
import './OTPInput.css';

/**
 * Controlled OTP input component
 *
 * props:
 * - length: number of boxes (6)
 * - value: string containing digits ("123456")
 * - onChange: function(newValue: string)
 * - onComplete: function(value: string) called when all boxes are filled
 * - disabled: boolean
 * - error: boolean (for styling)
 */
const OTPInput = ({ length, value, onChange, onComplete, disabled, error }) => {
  const inputsRef = useRef([]);

  // ensure value is always string of correct length
  const getDigits = () => (value || '').split('').slice(0, length);

  const focusInput = (idx) => {
    const input = inputsRef.current[idx];
    if (input) input.focus();
  };

  const handleChange = (e, idx) => {
    const digit = e.target.value.replace(/[^0-9]/g, '');
    if (!digit && value[idx]) {
      // clearing current box
      const newVal = value.substring(0, idx) + '' + value.substring(idx + 1);
      onChange(newVal);
      return;
    }

    if (digit) {
      let newVal = value;
      if (newVal.length < length) {
        newVal = newVal.padEnd(length, ' ');
      }
      newVal =
        newVal.substring(0, idx) + digit.charAt(0) + newVal.substring(idx + 1);
      newVal = newVal.substring(0, length);
      onChange(newVal);
      // move focus to next
      if (idx < length - 1) focusInput(idx + 1);
    }
  };

  const handleKeyDown = (e, idx) => {
    if (e.key === 'Backspace') {
      if (value[idx]) {
        // clear current
        const newVal =
          value.substring(0, idx) + '' + value.substring(idx + 1);
        onChange(newVal);
      } else if (idx > 0) {
        focusInput(idx - 1);
      }
    }
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const paste = e.clipboardData.getData('Text').trim();
    const digits = paste.replace(/\D/g, '').slice(0, length);
    if (digits) {
      const padded = digits.padEnd(length, '');
      onChange(padded);
      // move focus to end or first empty
      const nextIdx = digits.length < length ? digits.length : length - 1;
      focusInput(nextIdx);
    }
  };

  useEffect(() => {
    // when component mounts focus first empty box
    const idx = (value || '').length > 0 ? (value || '').length : 0;
    if (inputsRef.current[idx]) {
      inputsRef.current[idx].focus();
    }

    // notify complete
    if (onComplete && value && value.length === length && !value.includes('')) {
      onComplete(value);
    }
  }, [value, length, onComplete]);

  const digits = getDigits();

  return (
    <div className={`otp-input-container ${error ? 'error' : ''}`}>
      {Array.from({ length }).map((_, idx) => (
        <input
          key={idx}
          type="text"
          inputMode="numeric"
          maxLength="1"
          value={digits[idx] || ''}
          disabled={disabled}
          ref={(el) => (inputsRef.current[idx] = el)}
          onChange={(e) => handleChange(e, idx)}
          onKeyDown={(e) => handleKeyDown(e, idx)}
          onFocus={(e) => e.target.select()}
          onPaste={handlePaste}
          className="otp-box"
          autoFocus={idx === 0}
        />
      ))}
    </div>
  );
};

export default OTPInput;
